from collections import Counter
def comps(g,bg):
    H,W=len(g),len(g[0]); seen=set(); out=[]
    for i in range(H):
        for j in range(W):
            if g[i][j]!=bg and (i,j) not in seen:
                st=[(i,j)]; cells=[]
                seen.add((i,j))
                while st:
                    a,b=st.pop(); cells.append((a,b))
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+da,b+db
                        if 0<=x<H and 0<=y<W and g[x][y]!=bg and (x,y) not in seen:
                            seen.add((x,y)); st.append((x,y))
                out.append(cells)
    return out
def f2(g):
    bg=Counter(v for r in g for v in r).most_common(1)[0][0]
    cs=comps(g,bg)
    seed=max(cs,key=len)
    rs=[r for r,_ in seed]; cls=[c for _,c in seed]
    r0,r1,c0,c1=min(rs),max(rs),min(cls),max(cls)
    h,w=r1-r0+1,c1-c0+1
    pat=[[g[r0+a][c0+b] for b in range(w)] for a in range(h)]
    O=[row[:] for row in g]
    for cell in cs:
        if len(cell)==1:
            i,j=cell[0]
            tr,tc=i-h//2,j-w//2
            for a in range(h):
                for b in range(w):
                    x,y=tr+a,tc+b
                    if 0<=x<len(g) and 0<=y<len(g[0]):
                        O[x][y]=pat[a][b]
    return O
